using AutoMapper;using AutoMapper.QueryableExtensions;using DoctorLoan.Application;using DoctorLoan.Application.Common.Extentions;using DoctorLoan.Application.Interfaces.Commons;using DoctorLoan.Application.Interfaces.Data;using DoctorLoan.Application.Models.Commons;using DoctorLoan.Customer.Application.Features.Customers;using DoctorLoan.Domain.Enums.Commons;using DoctorLoan.MedicalRecord.Application.Commons.Expressions;using DoctorLoan.MedicalRecord.Application.Features.Dtos;using MediatR;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Logging;namespace DoctorLoan.MedicalRecord.Application.Features.Queries;public class FilterMedicalRecordQuery : QueryParam, IRequest<Result<PaginatedList<MedicalRecordDto>>>{    [FromQuery(Name = "search")]    public string Search { get; set; }    public RequestFilter Filter { get; set; } = new RequestFilter();}public class RequestFilter : IFilter{    public StatusEnum? Status { get; set; }    public DateTimeOffset? DateCreated { get; set; }    public int? ParentId { get; set; }}public class FilterMedicalRecordQueryHandler : ApplicationBaseService<FilterCustomerQueryHandler>, IRequestHandler<FilterMedicalRecordQuery, Result<PaginatedList<MedicalRecordDto>>>{    private readonly IMapper _mapper;    public FilterMedicalRecordQueryHandler(ILogger<FilterCustomerQueryHandler> logger,                                 IApplicationDbContext context,                                 ICurrentRequestInfoService currentRequestInfoService,                                 ICurrentTranslateService currentTranslateService,                                 IDateTime dateTime, IMapper mapper)        : base(logger, context, currentRequestInfoService, currentTranslateService, dateTime)    {        _mapper = mapper;    }    public async Task<Result<PaginatedList<MedicalRecordDto>>> Handle(FilterMedicalRecordQuery request, CancellationToken cancellationToken)    {        var condition = PredicateBuilder.True<Domain.Entities.MedicalRecord.MedicalRecord>();        #region add conditions        if (!string.IsNullOrWhiteSpace(request.Search))        {            condition = condition.And(MedicalRecordExpression.IsContains(request.Search));        }        if (request.Filter.Status.HasValue)        {            condition = condition.And(s => s.Status == request.Filter.Status);        }        if (request.Filter.DateCreated.HasValue)        {            condition = condition.And(s => s.DateCreated == request.Filter.DateCreated);        }        #endregion        var queryable = _context.MedicalRecords                                .Include(s => s.Customer)                                .Include(s => s.CustomerAddresses)                                .Where(condition);        queryable = request.Params.sort.Trim().ToLower() switch        {            "name" => queryable.Sort(m => m.Customer.FullName, request.SortAsc),            "date" => queryable.Sort(m => m.DateCreated, request.SortAsc),            _ => queryable.Sort(m => m.Id, asc: false),        };        var (page, take, sort, asc) = request.Params;        var result = await queryable.ProjectTo<MedicalRecordDto>(_mapper.ConfigurationProvider)                                    .ToPagedListAsync(page, take, cancellationToken);        return Result.Success(result);    }}
